import json
import sys

items = json.loads(sys.stdin.readline())
limit = json.loads(sys.stdin.readline())
if type(limit) is not int or limit < 1:
    raise ValueError('maxItems must be a positive integer')
if not isinstance(items, list):
    raise ValueError('items must be an array')
if len(items) > limit:
    raise ValueError('items exceeds maxItems')
if any(not isinstance(item, str) or not item.strip() for item in items):
    raise ValueError('Every item must be a nonblank string')
print('items validated')
